function model(p) {
  // Simplified illustration: made-up scores (logits) for 12 candidate next words after one fixed context.
  // Real models score tens of thousands of tokens; the steps are the same.
  const context = 'The customer asked for a';
  const RAW = [['refund', 3.1], ['discount', 2.5], ['receipt', 2.2], ['callback', 1.8], ['manager', 1.6], ['replacement', 1.3],
    ['quote', 1.0], ['demo', 0.7], ['trial', 0.4], ['ticket', 0.1], ['coffee', -0.8], ['banana', -2.0]];
  const T = Math.round(Math.min(2, Math.max(0.1, p.temperature)) * 10) / 10;
  const topP = Math.round(Math.min(1, Math.max(0.5, p.topP)) * 100) / 100;
  const softmax = xs => { const mx = Math.max(...xs), e = xs.map(x => Math.exp(x - mx)), s = e.reduce((a, b) => a + b, 0); return e.map(x => x / s); };
  const base = softmax(RAW.map(r => r[1]));        // temperature 1
  const prob = softmax(RAW.map(r => r[1] / T));    // after temperature; RAW is sorted, so prob is sorted too
  // Top-p: the smallest set of most likely words whose probabilities add up to at least top-p (all words when top-p = 1).
  let keptCount = RAW.length, cum = 0;
  if (topP < 1) for (let i = 0; i < RAW.length; i++) { cum += prob[i]; if (cum >= topP - 1e-12) { keptCount = i + 1; break; } }
  const keptMass = prob.slice(0, keptCount).reduce((a, b) => a + b, 0);
  // One seeded draw u in [0, 1): walk the kept words' renormalised probabilities until they pass u.
  let s = 42;
  const rnd = () => { s = (s + 0x6D2B79F5) >>> 0; let t = s; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
  const u = rnd();
  let acc = 0, pick = keptCount - 1;
  for (let i = 0; i < keptCount; i++) { const lo = acc; acc += prob[i] / keptMass; if (u >= lo && u < acc) { pick = i; break; } }
  let c = 0;
  const tokens = RAW.map(([text, score], i) => {
    const t = { text, score, rank: i + 1, pBase: base[i], p: prob[i], cumBefore: c, kept: i < keptCount, pFinal: i < keptCount ? prob[i] / keptMass : 0, picked: i === pick };
    c += prob[i];
    return t;
  });
  const pc = v => (v * 100 < 1 ? (v * 100).toFixed(1) : Math.round(v * 100)) + '\u00a0%';
  const steps = [
    { key: 'raw', t: 0, title: '1 · Raw scores', note: 'The model gives every candidate word a score (a logit). Higher means more likely, but these are not probabilities yet.' },
    { key: 'softmax', t: 2.5, title: '2 · Softmax', note: 'Softmax turns scores into probabilities that add up to 100 %: "' + RAW[0][0] + '" gets ' + pc(base[0]) + '.' },
    { key: 'temperature', t: 5, title: '3 · Temperature ' + T.toFixed(1), note: T < 1 ? 'Temperature ' + T.toFixed(1) + ' divides the scores before softmax: likely words grow, unlikely ones shrink. "' + RAW[0][0] + '" now has ' + pc(prob[0]) + '.'
      : T > 1 ? 'Temperature ' + T.toFixed(1) + ' flattens the odds: unlikely words gain ground. "' + RAW[0][0] + '" drops to ' + pc(prob[0]) + '.' : 'Temperature 1.0 leaves the probabilities unchanged.' },
    { key: 'topp', t: 7.5, title: '4 · Top-p ' + topP.toFixed(2), note: topP < 1 ? 'Keep the most likely words until their total reaches ' + Math.round(topP * 100) + ' %: ' + (keptCount === 1 ? 'only "' + RAW[0][0] + '" survives (' + pc(keptMass) + ').' : keptCount + ' of 12 words survive (' + pc(keptMass) + ').') : 'Top-p 1.00 keeps all 12 words in play.' },
    { key: 'pick', t: 10, title: '5 · Sample one word', note: '' }
  ];
  const summary = 'Temperature ' + T.toFixed(1) + ' and top-p ' + topP.toFixed(2) + ' keep ' + keptCount + ' of 12 words; the seeded draw picked "' + RAW[pick][0] + '" (' + pc(tokens[pick].pFinal) + ' after renormalising).';
  steps[4].note = 'A random number u = ' + u.toFixed(2) + ' lands on "' + RAW[pick][0] + '" among the kept words, renormalised to 100 %.';
  return { context, temperature: T, topP, tokens, keptCount, keptMass, u, pick, picked: RAW[pick][0], topToken: RAW[0][0], topProb: prob[0],
    steps, duration: 12.5, markers: steps.map(x => x.t), summary };
}

