function check(p) {
  const m = model(p), t = m.tokens, sum = k => t.reduce((a, x) => a + x[k], 0);
  const sumsOk = [sum('pBase'), sum('p'), sum('pFinal')].every(v => Math.abs(v - 1) < 1e-9);
  const sorted = t.every((x, i) => i === 0 || t[i - 1].p >= x.p);
  const mass = k => t.slice(0, k).reduce((a, x) => a + x.p, 0), k = m.keptCount;
  const minimal = m.topP >= 1 ? k === t.length : mass(k) >= m.topP - 1e-12 && (k === 1 || mass(k - 1) < m.topP - 1e-12);
  const flagsOk = t.every((x, i) => x.kept === (i < k));
  const lo = m.temperature > 0.1 ? Math.round((m.temperature - 0.1) * 10) / 10 : 0.1, hi = lo === m.temperature ? m.temperature + 0.1 : m.temperature;
  const pLo = model(Object.assign({}, p, { temperature: lo })).topProb, pHi = model(Object.assign({}, p, { temperature: hi })).topProb;
  const pickOk = t[m.pick].kept && t[m.pick].picked && t.filter(x => x.picked).length === 1;
  const pc = v => (v * 100).toFixed(1) + ' %';
  return {
    pass: sumsOk && sorted && minimal && flagsOk && pLo > pHi && pickOk,
    detail: 'Probabilities sum to ' + sum('p').toFixed(3) + '; top-p ' + m.topP.toFixed(2) + ' keeps ' + (k === 1 ? 'only the most likely word' : 'the ' + k + ' most likely words') + ' (' + pc(mass(k)) + (k > 1 && m.topP < 1 ? ', ' + (k - 1) + ' would give only ' + pc(mass(k - 1)) : '') +
      '); "' + m.topToken + '" has ' + pc(pLo) + ' at temperature ' + lo.toFixed(1) + ' versus ' + pc(pHi) + ' at ' + hi.toFixed(1) + '; the pick "' + m.picked + '" is in the kept set.'
  };
}
